            tx, ty = t
            dist = abs(tx - current[0]) + abs(ty - current[1])
            if dist < min_dist:
                min_dist = dist
                target_pos = (tx, ty)
        return target_pos

    def move_towards(target):
        tx, ty = target
        dx, dy = 0, 0
        if tx > x:
            dx = 1
        elif tx < x:
            dx = -1
