            dy = 1
        elif ty < y:
            dy = -1
        return [dx, dy]

    if mode == 'resource_collection':
        target = find_nearest(resources, own_pos)
        if target:
            return move_towards(target)

    elif mode == 'pursuit_evasion':
        target = find_nearest(opponents, own_pos)
        if target:
            return move_towards(target)

    elif mode == 'territory_control':
        target = find_nearest(territories, own_pos)
        if target:
            return move_towards(target)

    return [0, 0]

